use genex::prelude::*;

/// One wall kind: colour, normal and roughness maps from one CC0 set, so it takes the light as plaster does.
fn wall_kind(set: &str) -> Material {
    Material::color(Color::WHITE)
        .with_base_texture(&format!("cc0/{set}/color.jpg"))
        .with_normal_texture(&format!("cc0/{set}/normal.jpg"), 1.0)
        .with_metal_rough_texture(&format!("cc0/{set}/rough.jpg"))
        .with_untextured_color(Color::rgb(150, 146, 138))
}

/// A wall drawn as ~2 m panels: a cube's texture spans each face once, so short panels keep the texel size even.
fn draw_wall(frame: &mut Frame, from: Vec3, to: Vec3, height: f32, thick: f32, kinds: &[Material], seed: u32) {
    let run = to - from;
    let panels = (run.length() / 2.0).round().max(1.0) as u32;
    let step = run / panels as f32;
    frame.tag("building");
    for i in 0..panels {
        let centre = from + step * (i as f32 + 0.5) + vec3(0.0, height * 0.5, 0.0);
        let size = vec3(step.length().max(thick), height, thick);
        let yaw = genex::math::atan2(step.x, step.z);
        let kind = &kinds[((seed + i * 7) as usize) % kinds.len()]; // seeded, so neighbours differ
        frame.cube_with(Transform::from_translation(centre).with_rotation(Quat::from_rotation_y(yaw)).with_scale(size), kind);
    }
}
